#include <vector>

// Example test case: Earth orbit
void testEarthOrbit() {
    // Earth's mass (kg) and orbital radius (m)
    double earthMass = 5.972e24;
    double sunMass = 1.9885e30;
    double orbitRadius = 1.496e11; // 1 AU

    double force = calculateGravitationalForce(sunMass, earthMass, orbitRadius);
    double period = calculateOrbitalPeriod(orbitRadius, sunMass, G);

    std::cout << "Gravitational force between Earth and Sun: " << force << " N" << std::endl;
    std::cout << "Earth's orbital period: " << period / (365 * 24 * 60 * 60) << " years" << std::endl;
    // Real numbers: ≈ 3.54e22 N and 1 year respectively
}

// Example test case: Two-body system
void testTwoBodyInteraction() {
    // Two equal masses, 10^24 kg each, separated by 1 million km (1e9 m)
    double mass1 = 1e24;
    double mass2 = 1e24;
    double distance = 1e9;

    double force = calculateGravitationalForce(mass1, mass2, distance);
    std::cout << "Forces between two 10^24 kg bodies at 1 million km: " << force << " N" << std::endl;
    // Expected to be near G * 1e48 / (1e9)^3 = G * 1e21 ≈ 6.67e10 N
}
